-- READ-ONLY verification. Run on leocapin_main_v1 AFTER 02_loan_app_upgrade.sql.
-- Compares the live schema with backend/website/models.py (audit_logs is skipped: its live enum/jsonb
-- columns differ from the model only cosmetically). Expected result: 0 rows.
-- Re-generate this file if models.py changes.
with exp as (select t, split_part(x,':',1) c, case substr(split_part(split_part(x,':',2),'!',1),1,1) when 'v' then 'character varying' when 't' then 'text' when 'i' then 'integer' when 'f' then 'double precision' when 'n' then 'numeric' when 'd' then 'timestamp%' when 'b' then 'boolean' else 'json' end ty, x like '%!' nn from (values ('applicant_documents','id:v!,applicant_id:v!,application_id:v,filename:v!,filepath:v!,filetype:v,document_type:v!,uploaded_at:d,status:v,admin_comment:t'),('applicants','id:v!,kra_pin:v,name:v!,id_number:v,phone_number:v!,email:v!,password:v!,role:v!,loan_limit:i,payroll_number:v,applicant_status:v,interest_rate:f,applicant_type:v!,created_at:d,notes:t'),('application_audits','id:v!,application_id:v!,application_old_loan_amount:f!,application_new_loan_amount:f!,application_old_repayment_amount:f!,application_new_repayment_amount:f!,field_name:v!,old_status:v,new_status:v!,changed_by_email:v!,changed_by_role:v!,changed_by_company:v!,changed_at:d!,notes:t'),('application_documents','id:v!,application_id:v!,filename:v!,filepath:v!,filetype:v,document_type:v!,document_passcode:v,uploaded_at:d'),('applications','id:v!,employment_type:v,company:v,employment_nature:v,payroll_number:v,designation:v,is_first_time_applicant:v!,month_one:v!,month_two:v!,month_three:v!,loan_type:v!,loan_purpose:v!,amount_applied:n!,processing_fees:n!,access_fees:n!,legal_fees:n!,disbursement_amount:n!,repayment_amount:n!,outstanding_balance:n!,loan_product:v,duration_months:i,late_payment_fee:n!,collection_fee:n!,repayment_status:v!,loan_status:v!,hr_status:v!,interest_rate:v!,created_at:d,partially_paid_date:d,partially_paid_count:i,interest_charged_date:d,interest_charged_count:i,due_date:d,memo:v,month:v,notes:t,applicant_id:v!,applicant_role:v!'),('companies','id:v!,name:v!,code:v!,hr_email:v,contact_person:v,contact_phone:v,interest_rate:f!,processing_fee_rate:f!,access_fee_rate:f!,legal_fee:f!,repayment_cycle:v!,status:v!,bank_name:v,bank_account_number:v,bank_branch:v,notes:t,created_at:d'),('confirmation_documents','id:v!,filename:v!,filepath:v!,filetype:v,uploaded_at:d,email_id:v!'),('emails','id:v!,application_id:v!,recipient:v!,subject:v!,confirmation_text:t!,status:v!,created_at:d'),('hr_emails','id:v!,application_id:v!,recipient:v!,subject:v!,body:t!,company:v!,status:v!,created_at:d'),('parsed_transactions','id:v!,applicant_id:v!,statement_id:v!,date:d!,description:v!,reference:v,money_in:f,money_out:f,balance:f,category:v,is_internal_transfer:b,created_at:d'),('statement_entries','id:v!,applicant_id:v!,application_id:v,memo:v!,credit:n!,debit:n!,balance:n!,date:d,external_reference:v,idempotency_key:v'),('statement_uploads','id:v!,applicant_id:v!,filename:v!,filepath:v!,source:v,password:v,is_parsed:b,parsing_error:t,uploaded_at:d'),('transaction_keyword_mappings','id:v!,keyword:v!,category:v!,added_by:v,created_at:d'),('users','id:v!,name:v!,email:v!,number:v!,password:v!,role:v!,created_at:d,reset_token:v,reset_token_expiry:d')) v(t,s), regexp_split_to_table(s, ',') x), live as (select table_name t, column_name c, data_type ty, is_nullable='NO' nn from information_schema.columns where table_schema='public') select 'missing in live' k, e.t, e.c, e.ty||(case when e.nn then ' NOT NULL' else '' end) d from exp e left join live l on l.t=e.t and l.c=e.c where l.c is null and e.t in (select t from live) union all select 'type/null differs', e.t, e.c, 'repo '||e.ty||(case when e.nn then ' NOT NULL' else '' end)||' / live '||l.ty||(case when l.nn then ' NOT NULL' else '' end) from exp e join live l on l.t=e.t and l.c=e.c where l.ty not like e.ty or l.nn<>e.nn union all select 'extra in live', l.t, l.c, l.ty from live l left join exp e on l.t=e.t and l.c=e.c where e.c is null and l.t in (select t from exp) order by 1,2,3;
